parameters.text:
=Evaluate this customer return request against the return policy.

Order number: {{ $json.body.order_number }}
Customer email: {{ $json.body.customer_email }}
Reason: {{ $json.body.reason }}
Description: {{ $json.body.description }}

parameters.responseBody:
={{ JSON.stringify({
  status: "received",
  message: "Your return request has been received and is being reviewed. You will hear from us shortly.",
  order_number: $('When Return Requested').item.json.body.order_number
}) }}

parameters.text:
=:mag: *Return request needs human review*
*Order:* {{ $('When Return Requested').item.json.body.order_number }}
*Customer:* {{ $('When Return Requested').item.json.body.customer_email }}
*Reason:* {{ $('When Return Requested').item.json.body.reason }}
*Description:* {{ $('When Return Requested').item.json.body.description }}

*AI Decision:* {{ $('Return Evaluation Agent').item.json.output.decision }}
*Confidence:* {{ $('Return Evaluation Agent').item.json.output.confidence }}
*Reasoning:* {{ $('Return Evaluation Agent').item.json.output.reasoning }}
*Concerns:* {{ $('Return Evaluation Agent').item.json.output.concerns.join(", ") || "None" }}

parameters.jsonBody:
={{ JSON.stringify({
  order_number: $('When Return Requested').item.json.body.order_number,
  customer_email: $('When Return Requested').item.json.body.customer_email,
  decision: $('Return Evaluation Agent').item.json.output.decision,
  reason: $('When Return Requested').item.json.body.reason,
  notify: true
}) }}

parameters.text:
=:rotating_light: *Automatic return processing FAILED — manual review needed*
*Order:* {{ $('When Return Requested').item.json.body.order_number }}
*Customer:* {{ $('When Return Requested').item.json.body.customer_email }}
*AI Decision:* {{ $('Return Evaluation Agent').item.json.output.decision }}
*Confidence:* {{ $('Return Evaluation Agent').item.json.output.confidence }}
*Error:* {{ $json.error && $json.error.message ? $json.error.message : ($json.message || "Shopify API request failed") }}
